{"id":"6da21604-d4b4-46d9-8661-5bea6c20db9d","tr":true,"e_soru":"Platin kupası bulunan bir PlayStation oyununda, ana kupa listesinin gerekli bütün kupaları alınınca hangi kupa kazanılır?","e_sec":["Altın kupa","Platin kupa","Bronz kupa","Gümüş kupa"],"e_dogru":1,"e_aktif":true,"e_surum":2,"e_zorluk":2,"y_soru":"PlayStation'da bir oyunun tüm kupaları toplanınca hangi kupa kazanılır?","y_sec":["Altın","Platin","Kristal","Elmas"],"y_dogru":1,"y_aktif":true,"y_surum":1,"y_zorluk":2,"en":true,"ee_soru":"In a PlayStation game that offers one, which trophy is awarded after earning all trophies required for its main trophy list?","ee_sec":["Gold trophy","Platinum trophy","Bronze trophy","Silver trophy"],"ee_eskidi":false,"ye_soru":"On PlayStation, which trophy do you earn for collecting all of a game's trophies?","ye_sec":["Gold","Platinum","Crystal","Diamond"],"ye_eskidi":false,"at_simdi":false,"ye_eskidi_at":null}]$sd2veri$::jsonb) as x(
  id uuid, tr boolean,
  e_soru text, e_sec jsonb, e_dogru smallint, e_aktif boolean, e_surum integer, e_zorluk smallint,
  y_soru text, y_sec jsonb, y_dogru smallint, y_aktif boolean, y_surum integer, y_zorluk smallint,
  en boolean, ee_soru text, ee_sec jsonb, ee_eskidi boolean,
  ye_soru text, ye_sec jsonb, ye_eskidi boolean, at_simdi boolean, ye_eskidi_at timestamptz);

do $sd2$
declare
  v_n int;
  v_kayma text;
  v_tr int;
  v_en int;
begin
  select count(*) into v_n from _sd2;
  if v_n <> 1931 then raise exception 'soru-duzelt-2 geri-al: veri satırı % (beklenen 1931)', v_n; end if;

  -- Koruma: her hedef satır ya başlangıç (e_*) ya hedef (y_*) hâlinde olmalı. Üçüncü bir hâl
  -- (yedekten sonra başkası değiştirmiş) varsa hiçbir satır yazılmaz, işlem durur.
  select string_agg(x.id::text, ', ') into v_kayma
    from _sd2 x left join public.questions q on q.id = x.id
   where q.id is null
      or (x.tr and (q.soru, q.secenekler, q.dogru_cevap, q.aktif, q.surum, q.zorluk)
                   is distinct from (x.e_soru, x.e_sec, x.e_dogru, x.e_aktif, x.e_surum, x.e_zorluk)
              and (q.soru, q.secenekler, q.dogru_cevap, q.aktif, q.surum, q.zorluk)
                   is distinct from (x.y_soru, x.y_sec, x.y_dogru, x.y_aktif, x.y_surum, x.y_zorluk))
      or (not x.tr and (q.soru, q.secenekler, q.dogru_cevap, q.aktif, q.surum, q.zorluk)
                   is distinct from (x.e_soru, x.e_sec, x.e_dogru, x.e_aktif, x.e_surum, x.e_zorluk));
  if v_kayma is not null then raise exception 'soru-duzelt-2 geri-al: TR kayma, işlem durdu: %', v_kayma; end if;

  select string_agg(x.id::text, ', ') into v_kayma
    from _sd2 x left join public.question_translations t on t.question_id = x.id and t.dil = 'en'
   where t.question_id is null
      or (x.en and (t.soru, t.secenekler, t.eskidi) is distinct from (x.ee_soru, x.ee_sec, x.ee_eskidi)
              and (t.soru, t.secenekler, t.eskidi) is distinct from (x.ye_soru, x.ye_sec, x.ye_eskidi))
      or (not x.en and (t.soru, t.secenekler, t.eskidi) is distinct from (x.ee_soru, x.ee_sec, x.ee_eskidi));
  if v_kayma is not null then raise exception 'soru-duzelt-2 geri-al: EN kayma, işlem durdu: %', v_kayma; end if;

  -- Yalnız id eşleşen ve hâlâ başlangıç hâlindeki satırlar yazılır; hedef hâldekiler atlanır (idempotent).
  update public.questions q
     set soru = x.y_soru, secenekler = x.y_sec, dogru_cevap = x.y_dogru,
         aktif = x.y_aktif, surum = x.y_surum, zorluk = x.y_zorluk
    from _sd2 x
   where q.id = x.id and x.tr
     and (q.soru, q.secenekler, q.dogru_cevap, q.aktif, q.surum, q.zorluk)
         is not distinct from (x.e_soru, x.e_sec, x.e_dogru, x.e_aktif, x.e_surum, x.e_zorluk);
  get diagnostics v_tr = row_count;

  update public.question_translations t
     set soru = x.ye_soru, secenekler = x.ye_sec, eskidi = x.ye_eskidi,
         eskidi_at = case when x.at_simdi then now() else x.ye_eskidi_at end
    from _sd2 x
   where t.question_id = x.id and t.dil = 'en' and x.en
     and (t.soru, t.secenekler, t.eskidi) is not distinct from (x.ee_soru, x.ee_sec, x.ee_eskidi);
  get diagnostics v_en = row_count;

  raise notice 'soru-duzelt-2 geri-al: TR % satır, EN % satır yazıldı', v_tr, v_en;
end $sd2$;

drop table if exists pg_temp._sd2;

-- Kategori havuz önbelleği aktif/pasif değişimine göre yenilenir.
select public.kategori_havuz_yenile();
commit;
